private long getDirSize(File file) {
    long size = 0L;
    if (file.isDirectory()) {
        File[] files = file.listFiles();
        if (files != null) {
            for (File f : files) {
                size += getDirSize(f);
            }
        }
    } else {
        size = file.length();
    }
    return size;
}

